item.command:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$tracked = @(
'"'app\\page.tsx',
'app\\(gateway)\\page.tsx',
'app\\(systems)\\systems\\page.tsx',
'app\\(studio)\\studio\\page.tsx',
'app\\(gateway)\\about\\page.tsx',
'app\\(gateway)\\contact\\page.tsx',
'app\\admin\\page.tsx',
'tests\\routes.test.tsx',
'tests\\smoke.test.tsx',
'package.json',
'package-lock.json'
)
'APP_FILES'
Get-ChildItem -LiteralPath 'app' -Recurse -File | Sort-Object FullName | ForEach-Object { [IO.Path]::GetRelativePath((Get-Location).Path, "'$_.FullName) }
'"'PROHIBITED_COPY_SCAN'
"'$public = @('"'app\\(gateway)\\page.tsx','app\\(systems)\\systems\\page.tsx','app\\(studio)\\studio\\page.tsx','app\\(gateway)\\about\\page.tsx','app\\(gateway)\\contact\\page.tsx')
"'$matches = Select-String -LiteralPath $public -Pattern '"'\\b(prices?|pricing|testimonials?|awards?|stock|guarantee(?:d|s)?|guaranteed[ -]?results?)\\b' -AllMatches
if ("'$matches) { $matches | ForEach-Object { "$($_.Path):$($_.LineNumber):$($_.Line.Trim())" } } else { '"'NO_MATCHES' }
'MANIFEST_JSON_VALIDITY'
foreach ("'$manifest in @('"'package.json','package-lock.json')) { try { "'$null = Get-Content -LiteralPath $manifest -Raw | ConvertFrom-Json; "$manifest|VALID_JSON" } catch { "$manifest|INVALID_JSON|$($_.Exception.Message)" } }
'"'BASELINE_FINGERPRINTS'
foreach ("'$path in $tracked) {
  if (Test-Path -LiteralPath $path -PathType Leaf) {
    $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
    "$path|FILE|$hash"
  } else {
    "$path|ABSENT|-"
  }
}'

